# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('fierce','英 /fɪəs/；美 /fɪrs/','凶猛的；激烈的；强烈的','力量扑面而来，让人感到不好对付。','拉丁 ferus 野生、未驯服的 → 古法语 fer／fiers → 中古英语 fers → fierce。早期英语还曾有勇猛、骄傲的意思。',[['拉丁 ferus → 古法语 fer／fiers','野性的、强悍的'],['英语 fierce','凶猛；强烈、激烈']],'fierce competition 是竞争激烈，a fierce storm 是猛烈风暴。形容人的感情时不一定贬义：fierce loyalty 是极强的忠诚。抓住力度很强的感觉，比每次都译成凶恶更准确。','fierce competition；fierce opposition；a fierce storm；fierce loyalty。','furious 常强调愤怒；fierce 也能形容没有情绪的天气和竞争。声音大的人不一定 fierce，安静的人也可能有 fierce determination。',('Competition for the scholarship is fierce.','这项奖学金的竞争非常激烈。'),('She felt a fierce loyalty to her friends.','她对朋友怀有强烈的忠诚。'),sources=['https://www.etymonline.com/word/fierce','https://en.wiktionary.org/wiki/fierce#English']),
E('fiercely','英 /ˈfɪəsli/；美 /ˈfɪrsli/','猛烈地；激烈地；极其坚定地','把劲头拉满，不轻易让步或退缩。','fierce + -ly；中古英语已有对应副词形式。',[['中古英语 fers／fiers 与副词 fersly','强悍的 → 强悍地'],['现代英语 fiercely','猛烈地；极其坚定或强烈地']],'fight fiercely 是奋力战斗，fiercely independent 是非常独立、不愿依赖别人。后者不是凶巴巴地独立，而是对独立这件事坚持得很强烈。','fiercely independent；fiercely competitive；oppose something fiercely。','fierce competition 用形容词修饰名词；compete fiercely 用副词修饰动词。fiercely independent 的副词则修饰形容词。',('The two teams competed fiercely for the title.','两支队伍为冠军展开激烈争夺。'),('Even as a child, she was fiercely independent.','即使在小时候，她也特别独立。'),sources=['https://en.wiktionary.org/wiki/fiercely#English']),
E('ferocious','英 /fəˈrəʊʃəs/；美 /fəˈroʊʃəs/','凶残的；凶猛的；异常激烈的','像猛兽全力扑过来，带着强烈的攻击性或冲击力。','取自拉丁 ferox 凶猛的，其变化形式中出现 feroc-；再以 -ous 形成英语形容词。ferox 与 ferus 野性的相关。',[['拉丁 ferus → ferox／feroc-','野性的 → 凶猛、强悍的'],['英语 ferocious','凶猛、残暴；极其强烈']],'a ferocious dog 是凶猛的狗，a ferocious attack 是猛烈攻击。也能夸张地说 a ferocious appetite，意思是胃口大得惊人，并不是吃饭的人真的残暴。','a ferocious attack；a ferocious animal；ferocious winds；a ferocious appetite。','ferocious 常比 fierce 更突出凶猛、攻击性。fierce loyalty 很自然，ferocious loyalty 则带更强烈、更刻意的修辞感。',('The hikers heard a ferocious growl from behind the fence.','徒步者听见篱笆后传来凶猛的低吼。'),('After the long swim, he had a ferocious appetite.','长时间游泳后，他胃口大得惊人。'),sources=['https://www.etymonline.com/word/ferocious','https://en.wiktionary.org/wiki/ferocious#English']),
E('ferociously','英 /fəˈrəʊʃəsli/；美 /fəˈroʊʃəsli/','凶猛地；猛烈地；极其激烈地','一个动作做得像猛攻一样，力度特别强。','ferocious + -ly，副词承接凶猛或极其强烈的意思。',[['英语 ferocious','凶猛、极其强烈的'],['英语 ferociously','以凶猛或极其强烈的方式']],'fight ferociously 可以写战斗，也可以比喻拼命争取；ferociously competitive 是竞争心或竞争程度极强。语气比普通的 very 更夸张，适合有意强调力度时用。','fight ferociously；defend something ferociously；ferociously competitive。','ferociously 和 fiercely 有重叠，但前者通常更猛、更有攻击画面；不是日常每个 very 的替换词。',('The dog barked ferociously at the stranger.','那只狗冲着陌生人凶猛地吠叫。'),('She defended her proposal ferociously during the debate.','辩论中，她极力维护自己的提案。'),sources=['https://en.wiktionary.org/wiki/ferociously#English','https://www.etymonline.com/word/ferocious']),
E('ferocity','英 /fəˈrɒsəti/；美 /fəˈrɑːsəti/','凶猛；猛烈程度；残暴','不只问有没有攻击，而是那股冲击到底有多猛。','法语 férocité 来自拉丁 ferocitas，源于 ferox／feroc-。英语 ferocity 借入时间早于 ferocious，不能把名词的历史写成由英语形容词直接加 -ity 产生。',[['拉丁 ferox／feroc- → ferocitas','凶猛的 → 凶猛这一性质'],['法语 férocité → 英语 ferocity','凶猛、残暴或猛烈程度']],'the ferocity of the storm 说风暴的猛烈，the ferocity of an attack 说攻击的凶狠程度。它把 ferocious 描写的感觉变成可以讨论的名词；现代词义相关，不代表历史上名词一定晚于形容词。','with ferocity；the ferocity of an attack；unexpected ferocity。','violence 常说暴力行为或强烈破坏；ferocity 更突出凶猛、凶狠的程度，常是对力量和姿态的评价。',('The ferocity of the storm surprised everyone.','风暴的猛烈程度让所有人吃惊。'),('The team fought back with unexpected ferocity.','这支队伍以出乎意料的猛烈劲头展开反击。'),sources=['https://www.etymonline.com/word/ferocity','https://en.wiktionary.org/wiki/ferocity#English'])]
ROOT=dict(id='C0417',meaning='凶猛；野性；强烈的力量',core='FEROC = FIERCE',image='从野兽的强悍，走向风暴、竞争和意志的强烈。',intro='拉丁 ferus 表示野生、未驯服；ferox 及词干 feroc- 表示凶猛、强悍。fierce 经法语传来，ferocious 与 ferocity 则保留了更明显的 feroc- 形状。',forms='ferus → 法语 fiers → fierce → fiercely；ferox／feroc- → ferocious → ferociously；ferox → ferocitas → 法语 férocité → ferocity。这是三条旁支，不是一个英语词依次长成所有词。',branches=[['强烈、激烈','fierce；fiercely'],['凶猛和猛烈程度','ferocious；ferociously；ferocity']],contrasts='fierce 和 ferocious 都能夸张描写，但不一定在骂人：fierce determination 可以赞扬决心。具体褒贬看它修饰的内容。',practice='The storm was fierce, and its ferocity caught the sailors by surprise.\n\n风暴很猛烈，它的强度让水手们措手不及。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_feroc',[ROOT]),('words_feroc',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
